// The handlers forward requests to the grpc endpoint over "conn".
func RegisterMemorystoreHandler(ctx context.Context, mux *runtime.ServeMux, conn *grpc.ClientConn) error {
	return RegisterMemorystoreHandlerClient(ctx, mux, NewMemorystoreClient(conn))
}

